    event: TAccountMetas[1];
    organizer: TAccountMetas[2];
    stakeMint: TAccountMetas[3];
    vault: TAccountMetas[4];
    treasuryTokenAccount: TAccountMetas[5];
    /** Where ticket money goes. Only needed when tickets are owed. */
    organizerTokenAccount?: TAccountMetas[6] | undefined;
    tokenProgram: TAccountMetas[7];
